using System;using System.IO;using System.Linq;using UnityEngine;using AntColony.Units;
public static class Native1112Death{public static string Run(){var p=UnityEngine.Object.FindAnyObjectByType<MeshyNativeMotionPlayer>();var body=p.CreateDeath(true);if(!body)throw new Exception("No native corpse");try{var playback=body.GetComponent<MeshyNativeCorpse>();typeof(MeshyNativeCorpse).GetField("elapsed",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(playback,100f);playback.SendMessage("Update");float bottom=float.PositiveInfinity;var mesh=new Mesh();foreach(var skin in body.GetComponentsInChildren<SkinnedMeshRenderer>().Where(s=>s.enabled)){skin.BakeMesh(mesh);foreach(var v in mesh.vertices)bottom=Mathf.Min(bottom,skin.transform.TransformPoint(v).y);}UnityEngine.Object.DestroyImmediate(mesh);float error=Mathf.Abs(bottom-body.transform.position.y);if(error>.01f)throw new Exception("Corpse floor error "+error);if(!body.GetComponentsInChildren<SkinnedMeshRenderer>().Any(s=>s.enabled&&s.name.StartsWith("Part_Hair_")))throw new Exception("Lost appearance");var result="Native death end pose floor error="+error+"; original rig + selected hair retained PASS";File.WriteAllText("work/animation-1112/death-check.txt",result);return result;}finally{UnityEngine.Object.DestroyImmediate(body);}}}
